def pgcd(a, b):
    while a != b:
        if a > b:
            a = a - b
        else:
            b = b - a
    return a


def ppcm(a, b):
    if a % b == 0:
        return a
    else:
        r = a % b
    return (a // 2) * ppcm(b, r)


def puissance(a, b):
    p = 1
    for i in range(2, b + 1):
        p *= a
    return p


def fact(a):
    f = 1
    for i in range(2, a + 1):
        f *= i
    return f


def premier(b):
    nb = 0
    for i in range(2, b):
        if b % i == 0:
            nb += 1
    return nb == 0


def fpremier(a):
    ch = ""
    d = 2
    while a != 1:
        if a % d == 0:
            ch += "*" + str(d)
            a //= d
        else:
            d += 1
    return ch[1:]


def div_3(b):
    if b % 3 == 0:
        return True
    else:
        return False

