from numpy import array


def saisie():
    n = int(input("n= "))
    while n % 2 != 0:
        n = int(input("n= "))
    return n


def remplire_mat(n, m):
    x = 1
    for i in range(n // 2):
        cf = n - 1 - i
        for j in range(i, cf + 1):
            m[i, j] = x
            x = x + 1
        for k in range(i + 1, cf + 1):
            m[k, cf] = x
            x = x + 1
        for l in range(cf - 1, i - 1, -1):
            m[cf, l] = x
            x = x + 1
        for e in range(cf - 1, i, -1):
            m[e, i] = x
            x = x + 1


def affichage(m, n):
    for l in range(n):
        for c in range(n):
            print(m[l, c], end=" ")
        print(" ")


# pp
