def transfer_f_t(f, t):
    global n

    ch = f.readline()
    while ch != "":
        t[n] = ch
        n += 1
        ch = f.readline()
    f.close()


def tri(t, n):
    for i in range(1, n):
        tmp = t[i]
        j = i
        while (j > 0) and (len(t[j - 1]) > len(tmp)):
            t[j] = t[j - 1]
            j = j - 1
        t[j] = tmp
    f.close()


def transfer_t_f(f, t, n):
    for i in range(n):
        f.write(t[i])
    f.close()


def affichage(f, n):
    for i in range(n):
        ch = f.readline()
        print(ch)
    f.close()


