    f1 = open("ipv4.txt", "r")
    f2 = open("ip_invalide.txt", "w")
    f3 = open("ipv4_ipv6.dat", "wb")
    ch = f1.readline()
    while ch != "":
        ipv4 = ch.strip()
        t = array([int()] * 4)
        for i in range(3):
            p = ch.find(".")
            t[i] = int(ch[0:p])
            ch = ch[p + 1:]
        t[3] = int(ch)
        if 0 <= t[0] <= 255 and 0 <= t[1] <= 255 and 0 <= t[2] <= 255 and 0 <= t[3] <= 255:
            e = {}
            e["ipv4"] = ipv4
            e["classe"] = determine_classe(t[0])
            e["ipv6"] = determine_ipv6(t[0], t[1], t[2], t[3])
            dump(e, f3)
        else:
            f2.write(ipv4 + "\n")
        ch = f1.readline()
    f1.close()
    f2.close()
    f3.close()


def determine_classe(x):
    bin = ""
    while x != 0:
        r = x % 2
        x = x // 2
        bin = str(r) + bin
    if bin[0] == "0":
        return "A"
    elif bin[1] == "0":
        return "B"
    elif bin[2] == "0":
        return "C"
    elif bin[3] == "0":
        return "D"
    else:
        return "E"


def determine_ipv6(w, x, y, z):
    hexa = convb10_b16(w) + convb10_b16(x) + convb10_b16(y) + convb10_b16(z)
    hexa = hexa[0:len(hexa) // 2] + ":" + hexa[len(hexa) // 2:]
    return hexa


def convb10_b16(x):
    hexa = ""
    while x != 0:
        r = x % 16
        x = x // 16
