from pickle import dump, load
from PyQt5.uic import loadUi
from PyQt5.QtWidgets import QApplication, QMessageBox, QTableWidgetItem


def ajout():
    f1 = open("chaines.txt", "a")
    if win.ch.text() == "" or len(win.ch.text()) > 9 or verifAlphaNum(win.ch.text()) == False:
        QMessageBox.critical(win, "Erreur de Saisie", "Saisir Une Chaine Alpha Numérique")
        return False
    else:
        f1.write(win.ch.text() + "\n")
        f1.close()


def verifAlphaNum(ch):
    i = 0
    ch = ch.upper()
    while i < len(ch) and ("A" <= ch[i] <= "Z" or "0" <= ch[i] <= "9"):
        i += 1
    return i == len(ch)


def afficher_f1():
    f1 = open("chaines.txt", "r")
    ch = f1.readline().strip()
    while ch != "":
        win.list_f1.addItem(ch)
        ch = f1.readline().strip()
    f1.close()


def remplir_f2():
    f1 = open("chaines.txt", "r")
    f2 = open("nombres.dat", "wb")
    ch = f1.readline()
    while ch != "":
        ch2 = ""
        for i in range(len(ch)):
            if "0" <= ch[i] <= "9":
                ch2 += ch[i]
        e = {}
        if ch2 == "":
            e["nbdec"] = 999999999
            e["mention"] = "ce n'est pas un nmbr dec"
        elif div11(ch2):
            e["nbdec"] = int(ch2)
            e["mention"] = "est div par 11"
        else:
            e["nbdec"] = int(ch2)
            e["mention"] = "n'est pas div par 11"
        dump(e, f2)
        ch = f1.readline()
    f1.close()
    f2.close()


def div11(ch):
    sp = 0
    smp = 0
    for i in range(len(ch)):
        if (i + 1) % 2 == 0:
            sp = sp + int(ch[i])
        else:
            smp = smp + int(ch[i])
    return(sp - smp) % 11 == 0


def afficher_f2():
    f2 = open("nombres.dat", "rb")
    eof = False
    i = 0
    while not eof:
        try:
            e = load(f2)
            win.table_f2.insertRow(i)
            win.table_f2.setItem(i, 0, QTableWidgetItem(str(e["nbdec"])))
            win.table_f2.setItem(i, 1, QTableWidgetItem(e["mention"]))
            i += 1
        except:
            eof = True
    f2.close()


