from pickle import dump, load
from PyQt5.uic import loadUi
from PyQt5.QtWidgets import QApplication, QMessageBox, QTableWidgetItem
from numpy import array

def ajout():
    k=int(win.k.text())
    if k<0:
        QMessageBox.critical(win,"erreur","il faut saisir un entier positif")
    else:
        k=win.k.text()
        QMessageBox.information(win,"erreur","ajout avec succee")
        win.btn2.setEnabled(True)


def afficher_f1():
    k=int(win.k.text())
    global m,n
    m[0,0]=0
    m[0,1]=1
    m[1,1]=1
    fin=False
    while not fin:
        n+=1
        u=m[0,n-1]+m[0,n-2]
        if u<=k:
            win.liste_k.addItem(str(u))
            print(u)
            m[0,n]=u
            m[1,n]=0
        fin=(u>=k)
    win.btn3.setEnabled(True)


def codage():
    f=open("decomp.dat","wb")
    e={}
    k=int(win.k.text())
    e["k"]=k
    global m,n
    if m[0,n-1]==k:
        n=n-1
    s=m[0,n-1]
    somme=str(s)
    c=n-2
    while s<k :
        if s+m[0,c]<=k:
            s+=m[0,c]
            somme=somme+"+"+str(m[0,c])
            m[1,c]=1
        c-=1
    e["somme"]=somme
    print(somme)
    dump(e,f)
    f.close()
    win.btn4.setEnabled(True)

def afficher_code():
    f=open("decomp.dat","rb")
    global m,n
    ch=""
    for i in range(1,n):
        ch+=str(m[1,i])
    j=0
    eof=False
    while not eof:
        try:
            e=load(f)
            win.table_k.insertRow(j)
            win.table_k.setItem(j, 0, QTableWidgetItem(str(e["k"])))
            win.table_k.setItem(j, 1, QTableWidgetItem(e["somme"]))
            win.table_k.setItem(j, 2, QTableWidgetItem(ch))
            j+=1
        except:
            eof=True
    f.close()




n=1
m=array([[int()] * 100] * 100)
app = QApplication([])
win = loadUi("interface_codage.ui")
win.show()
win.btn1.clicked.connect(ajout)
win.btn2.clicked.connect(afficher_f1)
win.btn3.clicked.connect(codage)
win.btn4.clicked.connect(afficher_code)
app.exec_()


